# worker-run-result.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/worker-run-result.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "state": {
            "const": "succeeded"
          }
        }
      },
      "then": {
        "properties": {
          "result": {
            "properties": {
              "report_ref": {
                "type": "string"
              }
            }
          },
          "run_state": {
            "enum": [
              "stopped",
              "terminal"
            ]
          },
          "stop_proof_ref": {
            "type": "string"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "state": {
            "const": "cancelled"
          }
        }
      },
      "then": {
        "properties": {
          "run_state": {
            "enum": [
              "stopped",
              "terminal"
            ]
          },
          "stop_proof_ref": {
            "type": "string"
          }
        },
        "required": [
          "cancel_request_ref"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "state": {
            "enum": [
              "unknown",
              "unreachable",
              "cancel_requested"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "stop_proof_ref": {
            "type": "null"
          }
        }
      }
    }
  ],
  "properties": {
    "attempt_id": {
      "minLength": 1,
      "type": "string"
    },
    "cancel_request_ref": {
      "type": [
        "string",
        "null"
      ]
    },
    "ended_at": {
      "format": "date-time",
      "type": [
        "string",
        "null"
      ]
    },
    "gateway_request_key": {
      "pattern": "^chd-key-v1:sha256:[0-9a-f]{64}$",
      "type": "string"
    },
    "last_observed_at": {
      "format": "date-time",
      "type": "string"
    },
    "owner": {
      "const": "controller"
    },
    "request_id": {
      "minLength": 1,
      "type": "string"
    },
    "reservation_id": {
      "minLength": 1,
      "type": "string"
    },
    "result": {
      "additionalProperties": false,
      "properties": {
        "artifact_refs": {
          "items": {
            "minLength": 1,
            "type": "string"
          },
          "type": "array"
        },
        "criteria_results_ref": {
          "type": [
            "string",
            "null"
          ]
        },
        "report_ref": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
        "report_ref",
        "artifact_refs",
        "criteria_results_ref"
      ],
      "type": "object"
    },
    "revision": {
      "minimum": 1,
      "type": "integer"
    },
    "run_id": {
      "minLength": 1,
      "type": "string"
    },
    "run_state": {
      "enum": [
        "not_started",
        "running",
        "stopped",
        "terminal",
        "unknown",
        "unreachable"
      ]
    },
    "schema_version": {
      "const": "chd.worker-run.v1"
    },
    "send_id": {
      "minLength": 1,
      "type": "string"
    },
    "started_at": {
      "format": "date-time",
      "type": [
        "string",
        "null"
      ]
    },
    "state": {
      "enum": [
        "queued",
        "admitted",
        "running",
        "stopped",
        "succeeded",
        "failed",
        "cancel_requested",
        "unknown",
        "unreachable",
        "cancelled"
      ]
    },
    "stop_proof_ref": {
      "type": [
        "string",
        "null"
      ]
    },
    "target": {
      "additionalProperties": false,
      "properties": {
        "credential_scope": {
          "pattern": "^profile:[^/]+/credential:[^/]+$",
          "type": "string"
        },
        "gateway_id": {
          "minLength": 1,
          "type": "string"
        },
        "gateway_url_ref": {
          "pattern": "^gateway:[^/]+$",
          "type": "string"
        }
      },
      "required": [
        "gateway_id",
        "gateway_url_ref",
        "credential_scope"
      ],
      "type": "object"
    },
    "worker": {
      "additionalProperties": false,
      "properties": {
        "agent_id": {
          "minLength": 1,
          "type": "string"
        },
        "profile_ref": {
          "pattern": "^profile:[^/]+$",
          "type": "string"
        },
        "role": {
          "const": "worker"
        }
      },
      "required": [
        "agent_id",
        "profile_ref",
        "role"
      ],
      "type": "object"
    }
  },
  "required": [
    "schema_version",
    "run_id",
    "request_id",
    "send_id",
    "attempt_id",
    "reservation_id",
    "owner",
    "worker",
    "target",
    "state",
    "run_state",
    "result",
    "stop_proof_ref",
    "cancel_request_ref",
    "gateway_request_key",
    "started_at",
    "ended_at",
    "last_observed_at",
    "revision"
  ],
  "title": "CHD WorkerRun durable result",
  "type": "object"
}
```
